TLM.f("Sancti/01-21",{"officium":"S. Agnetis Virginis et Martyris","rule":["vide C6;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","from":{"GradualeP":"Commune/C6"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:95-96"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui infírma mundi éligis, ut fórtia quæque confúndas: concéde propítius; ut, qui beátæ Agnétis Vírginis et Mártyris tuæ sollémnia cólimus, ejus apud te patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:1-8; 51:12"},{"k":"text","la":"Confitébor tibi, Dómine, Rex, et collaudábo te Deum, Salvatórem meum. Confitébor nómini tuo: quóniam adjútor et protéctor factus es mihi, et liberásti corpus meum a perditióne, a láqueo línguæ iníquæ et a lábiis operántium mendácium, et in conspéctu astántium factus es mihi adjutor. Et liberasti me secúndum multitúdinem misericórdiæ nóminis tui a rugiéntibus, præparátis ad escam, de mánibus quæréntium ánimam meam, et de portis tribulatiónum, quæ circumdedérunt me: a pressúra flammæ, quæ circúmdedit me, et in médio ignis non sum æstuáta: de altitúdine ventris inferi, et a lingua coinquináta, et a verbo mendácii, a rege iníquo, et a lingua injústa: laudábit usque ad mortem ánima mea Dóminum: quóniam éruis sustinéntes te, et líberas eos de mánibus géntium, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 25:4 25:6"},{"k":"text","la":"Quinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:3; 44:5"},{"k":"text","la":"Diffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et de ducet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe coronam, quam tibi Dóminus præparávit in ætérnum."},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, oleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:1-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines illae, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam."}],"Offertorium":[{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Afferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Hóstias, Dómine, quas tibi offérimus, propítius súscipe: et, intercedénte beáta Agnéte Vírgine et Mártyre tua, víncula peccatórum nostrórum absólve."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 25:4-6"},{"k":"text","la":"Quinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9f9c6ab7f4db3841":{"t":"Ps 118, 95-96, Ps 118, 1\n(Ps 118, 95-96) Na mene su vrebali grješnici da me upropaste, ali ja pazim na naredbe tvoje. Vidim da svršava sve, ma bilo ne znam kako veliko. Samo je tvoja zapovijed beskrajno uzvišena. (Ps 118, 1) Blago neokaljanima na životnom putu, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 95-96) Na mene su vrebali grješnici da me upropaste, ali ja pazim na naredbe tvoje. Vidim da svršava sve, ma bilo ne znam kako veliko. Samo je tvoja zapovijed beskrajno uzvišena.","kn":"(Ps. 118, 95, 96). Na mene vrebaju grješnici, da me upropaste, a ja razmišljam Tvoj zako-n. Gospodine! Vidjeh, da ima svršetak sve, ma kako bilo veliko, samo je zakon Tvoj neizmjeran i bez kraja-. (Aleluja. Aleluja). (Ps. 118, 1). Blago onima, koji su čista života, koji žive po zakonu Gospodnjem! Slava Ocu. Na mene.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"a9401c71c45d6d7f":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji izabireš slabo u svijetu da postidiš jako, dopusti milostivo da mi koji slavimo svetkovinu blažene Agneze djevice i mučenice tvoje osjetimo njezinu zaštitu kod tebe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući, vječni Bože, koji izabireš ono, što je slabo pred svijetom, da postidiš one, koji su jaki, dopusti milostivo, da mi, koji poštujenio^ spomen bi. Agneze, Tvoje djevice i mučenice, osjetimo njezin zagovor kod Tebe, po G. n.","knRef":"Kniewald 1942, str. 486–487 (snimka 244) (OCR)"},"507bd98af25a06ac":{"t":"Sir 51, 1-8 i 12\nČitanje knjige Mudrosti. Slavim te, Gospodine Kralju, i hvalim te, Bože, Spasitelju moj. Slavim ime tvoje, jer si postao mojim pomoćnikom i zaštitnikom, spasio si me od propasti od zamke opaka jezika i od usta koja govore laži, i stao si uza me protiv mojih neprijatelja. Po svojem velikom milosrđu oslobodio si me od progonitelja, koji riču i spremni su da me prožderu. iz ruku onih koji vrebaju na me, iz muka koje me okružuju, od sile plamena koji me opkolio i nisam izgorio u ognju, iz dubine ponora, od opakog jezika i lažnih riječi, od pakosnoga poglavice i nepravednih usta. Hvalit ću te Gospodine, sve do smrti, jer ti spašavaš one koji se uzdaju u tebe, i oslobađaš ih iz bezbožničkih ruku, Gospodine naš.","kn":"Čitanje Knjige mudrosti (Crkv. 51, 1-8. 12). Slavim te, Gospodine kralju, i hvalim te. Bože, moj Spasitelju. Slavim tvoje ime, jer si postao moj pomoćnik i zaštitnik i spasio si me od propasti, od zamke opaka jezika i od usana, koje govore laži i stao si uza me protiv mojih protivnika. I ipo velikom svom milosrđu oslobodio si me od neprijatelja, koji riču spremni, da me prožderu; iz ruku onih, koji vrebaju na me i iz muka, koje me okružuju; od sile plamena, koji me je opkolio, da nijesam izgorjela u ognju; iz dubine ponora, od pogana jezika i lažnih riječi, od pakosna kralja i nepravedna jezika. Hvalit ću te. Gospodine, sve do smrti, jer spašavaš one, koji se uzdaju u tebe i oslobađaš ih iz bezbožničkih ruku, Gospodine Bože najš.","knRef":"Kniewald 1942, str. 830–831 (snimka 416) (OCR)"},"8db3bc245967dd3d":{"t":"Ps 44, 3, Ps 44, 3\n( Ps 44, 3) Razlita je milina na usnama tvojim. Zbog toga te je Bog blagoslovio u vijeke. (Ps 44, 5) Radi istine i krotkosti i pravde vodit će te divno tvoja desnica.\n\nMt 25, 4 i 6\n<i>Aleluja</i>, <i>aleluja</i>.\nPet je mudrih djevica uzelo ulje u svojim posudama zajedno sa svjetiljkama. A o ponoći začu se vika: Evo dolazi zaručnik, iziđite ususret Kristu Gospodinu. <i>Aleluja</i>.","v":"ps → ∅","kn":"(Ps. 44, 3). Razllta je milost na usnama tvojim, toga radi blagoslovi te Bog uvijeke. Istine radi, i krotkosti i pravde vodit će te divno desnica tvoja.\n\nAleluja, aleluja (Mat. 25, 4, C). Pet mudrih djevica uze ulje u sudovima svojim sa žišcinia; a o ponoći stade vika: Eto ženika gdje ide, iziđite na susret Kristu Gospodinu. Aleluja.","knRef":"Kniewald 1942, str. 832–833 (snimka 417) (OCR)"},"04a5e5f3be261c56":{"t":"Mt 25, 1-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke i iziđoše u susret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika: Evo, ide zaručnik, iziđite mu u susret! Tada ustaše sve djevice i zapališe svoje svjetiljke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje su bile spremne, uđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte dakle, jer ne znate ni dana ni časa.","kn":"t Slijedi sv. evanđelje po Mateju (25, 1-13). U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke 1 iziđoše ususret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika; Evo, ide zaručnik, iziđite mu ususret! Tada ustadoše sve djevice i zapališe svoje svjetUjke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje'su bile spremne, uniđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte, dakle, jer ne znate ni dana ni časa!","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"805e908c21018a9c":{"t":"Ps 44, 15-16\nZa njom će poći pred Kralja djevice. Drugarice će njezine poći k tebi u radosti, poći će u hram Kralja Gospodina."},"95fdbe9bf650aa6b":{"t":"Gospodine, milostivo primi darove koje ti prikazujemo i po zagovoru blažene Agneze, djevice i mučenice tvoje, odriješi okove naših grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, milostivo žrtve, koje Ti prinosimo, i zagovorom blažene Agneze, djevice i mučenice Tvoje, razriješi okove naših grijeha, po G. n.","knRef":"Kniewald 1942, str. 486–487 (snimka 244) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"a487c4b958415356":{"t":"Mt 25, 4 i 6\nPet je mudrih djevica uzelo ulje u svojim posudama zajedno sa svjetiljkama. A o ponoći začu se vika: Evo dolazi zaručnik, iziđite ususret Kristu Gospodinu.","kn":"(Mt. 25, 4, 6.) Pet je mudrih djevica uzelo ulje u posudama svojim sa svjetiljkama; a o ponoći nasta vika: Evo ide zaručnik, iziđite ususrte Kristu Gospodinu!","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"77eef81bf0c58a4e":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskim jelom i pićem ponizno te molimo, Bože naš, da budemo zaštićeni molitvama onoga na čiji smo to spomen primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni :nebeskom hranom i pićem, ponizno Te molimo; Bože naš, da nas zaštite molitve onoga, kojega se spominjemo primajući Tvoje darove. Po G. n.","knRef":"Kniewald 1942, str. 476–477 (snimka 239) (OCR)"}}});
